const string html = """
    <table>
      <thead><tr><th>Name</th><th>Status</th></tr></thead>
      <tbody><tr><td>CF26</td><td>Ready</td></tr></tbody>
    </table>
    """;

var blocks  = NotionHtmlImporter.Import(html, pageId);
var table   = blocks.Single(b => b.Type == BlockType.Table);
var content = (ITableBlockContent)table.Content;

// true — the first row is all <th>
var hasHeader = content.HasHeaderRow;

var blocks = NotionHtmlImporter.Import(
    "<p><a href=\"javascript:alert(1)\">click</a></p>", pageId);

// the text survives, the link does not
var html = ((ITextBlockContent)blocks[0].Content).Html;   // "<a>click</a>"

// an <img> with an unsafe src produces no Image block at all
NotionHtmlImporter.Import("<img src=\"javascript:alert(1)\">", pageId);   // []
